class CountIntervals {
    std::map<int, int> intervals;
    int total;
public:
    CountIntervals() : total(0) {}

    void add(int left, int right) {
        auto it = intervals.upper_bound(right);
        int l = left, r = right;
        while (it != intervals.begin()) {
            auto prev = std::prev(it);
            if (prev->second < left) break;
            l = std::min(l, prev->first);
            r = std::max(r, prev->second);
            total -= (prev->second - prev->first + 1);
            intervals.erase(prev);
        }
        intervals[l] = r;
        total += (r - l + 1);
    }

    int count() {
        return total;
    }
};

class CountIntervals {
    private java.util.TreeMap<Integer, Integer> map;
    private int total;

    public CountIntervals() {
        map = new java.util.TreeMap<>();
        total = 0;
    }

    public void add(int left, int right) {
        Integer l = map.floorKey(right);
        int curL = left, curR = right;
        while (l != null && map.get(l) >= left) {
            int r = map.get(l);
            curL = Math.min(curL, l);
            curR = Math.max(curR, r);
            total -= (r - l + 1);
            map.remove(l);
            l = map.floorKey(right);
        }
        map.put(curL, curR);
        total += (curR - curL + 1);
    }

    public int count() {
        return total;
    }
}

var CountIntervals = function() {
    this.intervals = [];
    this.total = 0;
};

CountIntervals.prototype.add = function(left, right) {
    let newL = left, newR = right;
    let idx = 0;
    while (idx < this.intervals.length && this.intervals[idx][1] < left) {
        idx++;
    }
    let deleteCount = 0;
    let i = idx;
    while (i < this.intervals.length && this.intervals[i][0] <= right) {
        newL = Math.min(newL, this.intervals[i][0]);
        newR = Math.max(newR, this.intervals[i][1]);
        this.total -= (this.intervals[i][1] - this.intervals[i][0] + 1);
        deleteCount++;
        i++;
    }
    this.intervals.splice(idx, deleteCount, [newL, newR]);
    this.total += (newR - newL + 1);
};

CountIntervals.prototype.count = function() {
    return this.total;
};
